import{_ as r,o as t,c as a,a as n}from"./app.6a7c4e5b.js";const o={};function i(l,e){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="blake-chan" tabindex="-1"><a class="header-anchor" href="#blake-chan" aria-hidden="true">#</a> Blake Chan</h1><hr><p><a href="https://blog.csdn.net/smilejiasmile" target="_blank" rel="noopener noreferrer">Blog</a> <strong>\xB7</strong> <a href="https://github.com/ai-chen2050" target="_blank" rel="noopener noreferrer">Code</a> <strong>\xB7</strong> <a href="https://www.linkedin.com/in/blake-chen-2825a9118" target="_blank" rel="noopener noreferrer">LinkedIn</a> <strong>\xB7</strong> <a href="https://www.twitter.com/Mr_chen5694" target="_blank" rel="noopener noreferrer">Twitter</a> <strong>\xB7</strong> <a href="mailto:ai-chen2050@qq.com">Mail</a> <strong>\xB7</strong> <a href="https://ai-chen2050.github.io/" target="_blank" rel="noopener noreferrer">Home</a></p><p>I am a software engineer, innovator, doer, and Mr. Curious. I&#39;ve been digging into the web3 industry for many years, and I love the equal, transparent, and decentralized nature of web3. I am committed to advancing the web3 industry around the world.</p><p>These days I work across <strong>distributed systems, verifiable logical clocks (VLC), high-performance blockchains, AI \u2194 payments rails, and Lightning Network infrastructure</strong> \u2014 mostly as an open-source contributor to <a href="https://github.com/hetu-project" target="_blank" rel="noopener noreferrer">Hetu Project</a> and <a href="https://github.com/loka-network" target="_blank" rel="noopener noreferrer">Loka Network</a>.</p><p>I&#39;m also interested in applying modern mathematical principles and related algorithms to engineering, and in basic sciences such as sociology, economics, organization management, and mathematical physics. I have a positive and healthy attitude, am inclusive, and hold a firm belief in lifelong learning.</p><p>Previously, I received my master&#39;s degree in <a href="http://www.sei.ecnu.edu.cn/" target="_blank" rel="noopener noreferrer">Software Engineering</a> at <a href="https://www.ecnu.edu.cn/" target="_blank" rel="noopener noreferrer">East China Normal University</a> and my bachelor&#39;s degree in <a href="https://ss.jou.edu.cn/" target="_blank" rel="noopener noreferrer">New Energy Science and Engineering</a> at <a href="https://www.jou.edu.cn/" target="_blank" rel="noopener noreferrer">Jiangsu Ocean University</a>.</p><h2 id="experience" tabindex="-1"><a class="header-anchor" href="#experience" aria-hidden="true">#</a> Experience</h2><table><thead><tr><th>Company</th><th>Role</th><th>Period</th><th>Type</th></tr></thead><tbody><tr><td>Nagara Labs (<a href="https://github.com/hetu-project" target="_blank" rel="noopener noreferrer">Hetu</a> / <a href="https://github.com/loka-network" target="_blank" rel="noopener noreferrer">Loka</a>)</td><td>Senior Web3 / Distributed Systems Engineer</td><td>2024.04 \u2013 Present</td><td>Fulltime</td></tr><tr><td><a href="https://kamivision.com/" target="_blank" rel="noopener noreferrer">KAMI Vision</a></td><td>Senior Web3 / DePIN Engineer</td><td>2023.02 \u2013 2023.12</td><td>Fulltime</td></tr><tr><td><a href="https://www.linkedin.com/company/amberbtc/" target="_blank" rel="noopener noreferrer">Amber Group</a></td><td>Blockchain Infra Dev / Searcher</td><td>2022.04 \u2013 2022.12</td><td>Fulltime</td></tr><tr><td>Shanghai Jiansu Network Tech</td><td>Consortium Blockchain Dev</td><td>2020.05 \u2013 2022.04</td><td>Fulltime</td></tr><tr><td>Shanghai <a href="https://www.linkedin.com/company/onchain/" target="_blank" rel="noopener noreferrer">Distribution / Ontology</a></td><td>Blockchain Wallet &amp; Core Dev</td><td>2017.08 \u2013 2020.04</td><td>Fulltime</td></tr></tbody></table><h2 id="what-i-m-building-2024-\u2013-2026" tabindex="-1"><a class="header-anchor" href="#what-i-m-building-2024-\u2013-2026" aria-hidden="true">#</a> What I&#39;m Building (2024 \u2013 2026)</h2><h3 id="hetu-project-\u2014-causality-driven-infrastructure-for-the-ai-native-economy" tabindex="-1"><a class="header-anchor" href="#hetu-project-\u2014-causality-driven-infrastructure-for-the-ai-native-economy" aria-hidden="true">#</a> Hetu Project \u2014 Causality-driven infrastructure for the AI-native economy</h3><ul><li><strong><a href="https://github.com/hetu-project/hetu-chain" target="_blank" rel="noopener noreferrer">hetu-chain</a></strong> \u2014 The mainnet interface of the Hetu subnet ecosystem (Cosmos-SDK + EVM, evolved from Evmos).</li><li><strong><a href="https://github.com/hetu-project/Setu" target="_blank" rel="noopener noreferrer">Setu</a></strong> \u2014 A causally-driven distributed ledger system designed for AI-native economies (Rust).</li><li><strong><a href="https://github.com/hetu-project/causalitygraph" target="_blank" rel="noopener noreferrer">causalitygraph</a></strong> \u2014 Decentralized data-collaboration network that achieves fast, verifiable causality and data consistency off-chain.</li><li><strong><a href="https://github.com/hetu-project/prakasa" target="_blank" rel="noopener noreferrer">prakasa</a></strong> \u2014 Decentralized, privacy-preserving P2P GPU inference network built on Parallax.</li><li><strong><a href="https://github.com/hetu-project/hetu-checkpoint" target="_blank" rel="noopener noreferrer">hetu-checkpoint</a></strong> \u2014 Verification network providing multi-dimensional security guarantees.</li><li><strong><a href="https://github.com/hetu-project/aegean-consensus" target="_blank" rel="noopener noreferrer">aegean-consensus</a></strong> \u2014 BFT consensus protocol for multi-agent LLM systems.</li><li><strong><a href="https://github.com/hetu-project/PoCW" target="_blank" rel="noopener noreferrer">PoCW</a></strong> \u2014 Proof of Causality Work \u2014 a protocol I helped iterate on for verifiable causal computation.</li></ul><p>Earlier work on Hetu also included <strong>VLC / TEE-VLC / Chronos / zchronod</strong> \u2014 research and engineering on verifiable logical clocks running inside AWS Nitro Enclaves, integrated with libp2p, Sui&#39;s Mysticeti and FastPay-style protocols.</p><h3 id="loka-network-\u2014-lightning-network\u2013native-ai-payment-rails" tabindex="-1"><a class="header-anchor" href="#loka-network-\u2014-lightning-network\u2013native-ai-payment-rails" aria-hidden="true">#</a> Loka Network \u2014 Lightning-Network\u2013native AI payment rails</h3><ul><li><strong><a href="https://github.com/loka-network/loka-chain" target="_blank" rel="noopener noreferrer">loka-chain</a></strong> \u2014 Fully EVM-compatible chain with NeoBFT consensus and Block-STM parallel execution (forked &amp; re-architected from Cronos).</li><li><strong><a href="https://github.com/loka-network/loka-p2p-lnd" target="_blank" rel="noopener noreferrer">loka-p2p-lnd</a></strong> \u2014 Agentic-payments P2P Lightning node built natively on top of the Bitcoin Lightning Network.</li><li><strong><a href="https://github.com/loka-network/paycli" target="_blank" rel="noopener noreferrer">paycli</a></strong> \u2014 Single-binary Payment CLI + Go SDK for L402 / Lightning payments (the basis of <code>lokapay</code>).</li><li><strong><a href="https://github.com/loka-network/loka-prism-l402" target="_blank" rel="noopener noreferrer">loka-prism-l402</a></strong> \u2014 Reverse-proxy gateway that turns any API into a metered, micropayment-secured endpoint over HTTP 402.</li><li><strong><a href="https://github.com/loka-network/agents-pay-service" target="_blank" rel="noopener noreferrer">agents-pay-service</a></strong> \u2014 Open-source Loka agentic Lightning-payment system for multi-agent AI, built on LNbits.</li><li><strong><a href="https://github.com/loka-network/loka-nostr-middleware" target="_blank" rel="noopener noreferrer">loka-nostr-middleware</a></strong> \u2014 High-performance Rust Nostr relayer used by the Loka payment stack.</li></ul><h3 id="personal-open-source" tabindex="-1"><a class="header-anchor" href="#personal-open-source" aria-hidden="true">#</a> Personal open source</h3><ul><li><strong><a href="https://github.com/ai-chen2050/obsidian-wechat-public-platform" target="_blank" rel="noopener noreferrer">obsidian-wechat-public-platform</a></strong> \u2B50 150 \u2014 Publish Markdown notes from Obsidian straight to WeChat Official Account / \u767E\u5EA6\u767E\u5BB6\u53F7.</li><li><strong><a href="https://github.com/ai-chen2050/iso-relayer" target="_blank" rel="noopener noreferrer">iso-relayer</a></strong> \u2014 A high-performance, scalable ISO-relay for Nostr.</li><li><strong><a href="https://github.com/ai-chen2050/gluex" target="_blank" rel="noopener noreferrer">gluex</a></strong> \u2014 A small Solana-stack experiment for cross-protocol glue in web3.</li><li><strong><a href="https://github.com/ai-chen2050/ai-chen2050.github.io" target="_blank" rel="noopener noreferrer">ai-chen2050.github.io</a></strong> \u2014 Source code of this site (forked from <code>vuepress-theme-gungnir</code> and heavily modified).</li></ul><h2 id="earlier-highlights-2017-\u2013-2023" tabindex="-1"><a class="header-anchor" href="#earlier-highlights-2017-\u2013-2023" aria-hidden="true">#</a> Earlier highlights (2017 \u2013 2023)</h2><h3 id="_2023-\xB7-kami-vision-\u2014-depin-web3cam" tabindex="-1"><a class="header-anchor" href="#_2023-\xB7-kami-vision-\u2014-depin-web3cam" aria-hidden="true">#</a> 2023 \xB7 KAMI Vision \u2014 DePIN / Web3Cam</h3><ul><li><strong>zkCam</strong> \u2014 A decentralized identity &amp; video-evidence platform for IoT cameras: W3C DID + Schnorr ZKP authentication, proxy re-encryption for end-to-end sharing, on-chain integrity proofs. Designed the white-paper, the user / device / share-event data model and built most of the cloud-side APIs.</li><li><strong>Decentralized CDN (DCDN)</strong> \u2014 Researched Fleek / Saturn / Crust / IPFS-Cluster, then built a multi-node Gateway \u2192 IndexProvider \u2192 L1-node DCDN pipeline (libp2p + DHT discovery, BadgerDB index, multi-strategy cache, IPFS Cluster storage). Owned the L1 node, Gateway routing and the JSON-RPC interfaces between modules.</li><li><strong>OTA &amp; sharing service</strong> \u2014 Device OTA flow, proxy-re-encryption sharing, OSS alarm event pipeline, AWS SES email channel, multi-Edge user/sharing/billing APIs.</li></ul><h3 id="_2022-\xB7-amber-group-\u2014-on-chain-alpha-mev-infrastructure" tabindex="-1"><a class="header-anchor" href="#_2022-\xB7-amber-group-\u2014-on-chain-alpha-mev-infrastructure" aria-hidden="true">#</a> 2022 \xB7 Amber Group \u2014 On-chain alpha &amp; MEV infrastructure</h3><ul><li><strong>Alpha Explorer</strong> \u2014 Amber&#39;s in-house MEV / NFT-Arb detector &amp; PnL visualiser (Go, Task-Pipeline arch, MongoDB + Grafana). Owned the <strong>NFT-Arb mode</strong> end-to-end: ERC-721/1155 event parsing, profit calculation, OpenSea / LooksRare / X2Y2 / sudoswap / NFTX coverage, Grafana dashboards, and bridged in marketplace API keys.</li><li><strong>Chain-node optimisation</strong> \u2014 Optimised Fantom &amp; Tron full nodes for the searcher stack: P2P broadcast tweaks, event subscription, pending-tx push, plus a hand-rolled Tron Go SDK (none existed officially) so the trading team could quantify on SunSwap / JustLend.</li><li><strong>ETL &amp; observability</strong> \u2014 Built a Pulsar / ClickHouse / InfluxDB / Grafana / Tableau data pipeline for multi-chain (ETH/BSC/Polygon/FTM) buried-point collection, Dex-swap / lending-liquidation / Top-bot dashboards.</li></ul><h3 id="_2020-\u2013-2022-\xB7-jiansu-network-tech-\u2014-bevios-consortium-chain" tabindex="-1"><a class="header-anchor" href="#_2020-\u2013-2022-\xB7-jiansu-network-tech-\u2014-bevios-consortium-chain" aria-hidden="true">#</a> 2020 \u2013 2022 \xB7 Jiansu Network Tech \u2014 BEVIOS consortium chain</h3><ul><li><strong>BEVIOS</strong> \u2014 A graphene-plug-in consortium-chain base shipped to <em>\u4E0A\u6D77\u4E00\u7F51\u901A\u529E</em>, <em>\u4E1C\u65B9\u7F51</em> (digital-copyright traceability), and Shanghai Jinghua&#39;s NFT trading platform. Features: pluggable consensus (Raft / Async-Pipeline-BFT / BEVY), DAG-driven parallel execution, TEE-based privacy compute, WASM + EVM dual VM, commercially-metered resources (DPU / Bandwidth / dRAM / dROM), K8s/Docker BaaS deployment.</li><li>Personally drove tech selection (vs. Fisco-BCOS / ChainMaker), built the HistoryLog sync tool, integrated PostgreSQL to power a block explorer, added EVM-VM support, and shipped several system contracts.</li></ul><h3 id="_2017-\u2013-2020-\xB7-distribution-ontology-\u2014-custodian-wallets" tabindex="-1"><a class="header-anchor" href="#_2017-\u2013-2020-\xB7-distribution-ontology-\u2014-custodian-wallets" aria-hidden="true">#</a> 2017 \u2013 2020 \xB7 Distribution / Ontology \u2014 Custodian &amp; wallets</h3><ul><li><strong>Custodian</strong> \u2014 A B2B multi-currency digital-asset custody platform (BTC / ETH / EOS / ...). Built the new-currency wallet backend (Go Chain Engine + Java business side, RESTful, MySQL + Redis): node sync, deposit parsing, Ledger-backed legal-address generation, withdrawal, reconciliation and risk-control checks.</li><li>Earlier \u2014 built Ontology / Neo ecosystem tooling and contributed to wallet core dev for the team.</li></ul><h2 id="publications" tabindex="-1"><a class="header-anchor" href="#publications" aria-hidden="true">#</a> Publications</h2><ul><li><strong>Patent</strong> \u2014 <a href="https://www.zhangqiaokeyan.com/patent-detail/06120114021718.html" target="_blank" rel="noopener noreferrer">A general-purpose WASM contract virtual machine technical solution for cross-blockchain contract ecological integration and reuse.</a></li><li><strong>Patent</strong> \u2014 A real-time, online, multi-instance blockchain runtime VM intelligent management &amp; control platform.</li></ul><h2 id="off-keyboard" tabindex="-1"><a class="header-anchor" href="#off-keyboard" aria-hidden="true">#</a> Off-keyboard</h2><p>Wide range of interests \u2014 reading, thinking, and the development of basic sciences such as sociology, economics, organization management, and mathematical physics. Thanks for stopping by \u2014 if any of the above resonates, drop me a line or <strong>\u2B50 a repo</strong>.</p>',30)])])}var h=r(o,[["render",i],["__file","index.html.vue"]]);export{h as default};
